// Words for the month-page intro and FAQ (task 152 step 3), in every page language.
// Every value passed in is already formatted for the language (times, dates, durations);
// x = { n: city, mo: 'December 2026', fajrE, fajrEd, fajrL, fajrLd, magE, magEd, magL, magLd,
//       dayFirst, dayLast, change (duration or null), longer (bool), dst ({ date, fwd } | null),
//       ram ({ year, date | null } | null), eidF, eidA (dates or null), m (method), a (Asr) }.
export const MONTH_TEXT = {
  en: {
    dur: (h, m) => (h ? `${h} h ${m} min` : `${m} min`),
    introH: (n, mo) => `${n} in ${mo}`,
    intro: (x) => [
      `Fajr is earliest on ${x.fajrEd} at <b>${x.fajrE}</b> and latest on ${x.fajrLd} at <b>${x.fajrL}</b>.`,
      `Maghrib (Iftar) is earliest on ${x.magEd} at <b>${x.magE}</b> and latest on ${x.magLd} at <b>${x.magL}</b>.`,
      x.change ? `Daylight, from sunrise to Maghrib, ${x.longer ? 'grows' : 'shrinks'} from ${x.dayFirst} to ${x.dayLast} over the month (${x.longer ? '+' : '−'}${x.change}).` : `Daylight stays at about ${x.dayFirst} all month.`,
      x.dst && `Clocks go ${x.dst.fwd ? 'forward' : 'back'} one hour on ${x.dst.date}; the times in the table already include the change.`,
      x.ram && (x.ram.date ? `Ramadan ${x.ram.year} is expected to begin on ${x.ram.date}.` : `Part of Ramadan ${x.ram.year} falls in this month.`),
      x.eidF && `Eid al-Fitr is expected on ${x.eidF}.`,
      x.eidA && `Eid al-Adha is expected on ${x.eidA}.`,
    ],
    faq: (x) => [
      [`What time is Fajr in ${x.n} in ${x.mo}?`, `Fajr in ${x.n} ranges from ${x.fajrE} (${x.fajrEd}) to ${x.fajrL} (${x.fajrLd}) in ${x.mo}. The table above has the time for every day.`],
      [`What time is Maghrib in ${x.n} in ${x.mo}?`, `Maghrib in ${x.n} ranges from ${x.magE} (${x.magEd}) to ${x.magL} (${x.magLd}) in ${x.mo}.`],
      [`Which calculation method do these times use?`, `${x.m}, with the ${x.a} time for Asr. Your masjid may differ by a few minutes; follow its timetable for congregation.`],
      ...(x.ram ? [[`When is Suhoor and Iftar in ${x.n} during Ramadan ${x.ram.year}?`, 'Suhoor ends at Fajr and Iftar is at Maghrib. The Ramadan days are highlighted in the table; the start depends on the moon sighting your community follows.']] : []),
    ],
  },
  ar: {
    dur: (h, m) => (h ? `${h} س ${m} د` : `${m} د`),
    introH: (n, mo) => `${n} في ${mo}`,
    intro: (x) => [
      `أبكر فجر يوم ${x.fajrEd} عند <b>${x.fajrE}</b>، وآخره يوم ${x.fajrLd} عند <b>${x.fajrL}</b>.`,
      `أبكر مغرب (إفطار) يوم ${x.magEd} عند <b>${x.magE}</b>، وآخره يوم ${x.magLd} عند <b>${x.magL}</b>.`,
      x.change ? `${x.longer ? 'يطول' : 'يقصر'} النهار من الشروق إلى المغرب من ${x.dayFirst} إلى ${x.dayLast} خلال الشهر (${x.longer ? '+' : '−'}${x.change}).` : `يبقى النهار نحو ${x.dayFirst} طوال الشهر.`,
      x.dst && `${x.dst.fwd ? 'تُقدَّم' : 'تُؤخَّر'} الساعة ساعة واحدة يوم ${x.dst.date}؛ والجدول يشمل هذا التغيير.`,
      x.ram && (x.ram.date ? `يُتوقع أن يبدأ رمضان ${x.ram.year} يوم ${x.ram.date}.` : `يقع جزء من رمضان ${x.ram.year} في هذا الشهر.`),
      x.eidF && `يُتوقع عيد الفطر يوم ${x.eidF}.`,
      x.eidA && `يُتوقع عيد الأضحى يوم ${x.eidA}.`,
    ],
    faq: (x) => [
      [`متى الفجر في ${x.n} في ${x.mo}؟`, `يتراوح الفجر في ${x.n} بين ${x.fajrE} (${x.fajrEd}) و${x.fajrL} (${x.fajrLd}) في ${x.mo}. الجدول أعلاه فيه وقت كل يوم.`],
      [`متى المغرب في ${x.n} في ${x.mo}؟`, `يتراوح المغرب في ${x.n} بين ${x.magE} (${x.magEd}) و${x.magL} (${x.magLd}) في ${x.mo}.`],
      ['ما طريقة الحساب المستخدمة؟', `${x.m}، والعصر ${x.a}. قد يختلف مسجدك ببضع دقائق؛ اتبع جدوله لصلاة الجماعة.`],
      ...(x.ram ? [[`متى السحور والإفطار في ${x.n} في رمضان ${x.ram.year}؟`, 'ينتهي السحور عند الفجر والإفطار عند المغرب. أيام رمضان مظللة في الجدول، ويعتمد بدؤه على رؤية الهلال.']] : []),
    ],
  },
  ur: {
    dur: (h, m) => (h ? `${h} گھنٹے ${m} منٹ` : `${m} منٹ`),
    introH: (n, mo) => `${n}، ${mo}`,
    intro: (x) => [
      `سب سے جلدی فجر ${x.fajrEd} کو <b>${x.fajrE}</b> اور سب سے دیر سے ${x.fajrLd} کو <b>${x.fajrL}</b> ہے۔`,
      `سب سے جلدی مغرب (افطار) ${x.magEd} کو <b>${x.magE}</b> اور سب سے دیر سے ${x.magLd} کو <b>${x.magL}</b> ہے۔`,
      x.change ? `طلوعِ آفتاب سے مغرب تک دن اس مہینے ${x.dayFirst} سے ${x.dayLast} ${x.longer ? 'تک بڑھتا' : 'تک گھٹتا'} ہے (${x.longer ? '+' : '−'}${x.change})۔` : `دن پورا مہینہ تقریباً ${x.dayFirst} رہتا ہے۔`,
      x.dst && `${x.dst.date} کو گھڑیاں ایک گھنٹہ ${x.dst.fwd ? 'آگے' : 'پیچھے'} ہوتی ہیں؛ جدول میں یہ تبدیلی شامل ہے۔`,
      x.ram && (x.ram.date ? `رمضان ${x.ram.year} کا آغاز ${x.ram.date} کو متوقع ہے۔` : `رمضان ${x.ram.year} کا کچھ حصہ اس مہینے میں ہے۔`),
      x.eidF && `عید الفطر ${x.eidF} کو متوقع ہے۔`,
      x.eidA && `عید الاضحیٰ ${x.eidA} کو متوقع ہے۔`,
    ],
    faq: (x) => [
      [`${x.mo} میں ${x.n} میں فجر کب ہے؟`, `${x.mo} میں ${x.n} میں فجر ${x.fajrE} (${x.fajrEd}) سے ${x.fajrL} (${x.fajrLd}) تک ہے۔ اوپر جدول میں ہر دن کا وقت ہے۔`],
      [`${x.mo} میں ${x.n} میں مغرب کب ہے؟`, `${x.mo} میں ${x.n} میں مغرب ${x.magE} (${x.magEd}) سے ${x.magL} (${x.magLd}) تک ہے۔`],
      ['یہ اوقات کس طریقے سے نکالے گئے ہیں؟', `${x.m}، عصر ${x.a}۔ آپ کی مسجد کا وقت چند منٹ مختلف ہو سکتا ہے؛ جماعت کے لیے اس کا جدول دیکھیں۔`],
      ...(x.ram ? [[`رمضان ${x.ram.year} میں ${x.n} میں سحری اور افطار کب ہے؟`, 'سحری فجر پر ختم ہوتی ہے اور افطار مغرب پر ہے۔ رمضان کے دن جدول میں نمایاں ہیں؛ آغاز رویتِ ہلال پر منحصر ہے۔']] : []),
    ],
  },
  id: {
    dur: (h, m) => (h ? `${h} jam ${m} menit` : `${m} menit`),
    introH: (n, mo) => `${n} pada ${mo}`,
    intro: (x) => [
      `Subuh paling awal pada ${x.fajrEd} pukul <b>${x.fajrE}</b> dan paling akhir pada ${x.fajrLd} pukul <b>${x.fajrL}</b>.`,
      `Maghrib (berbuka) paling awal pada ${x.magEd} pukul <b>${x.magE}</b> dan paling akhir pada ${x.magLd} pukul <b>${x.magL}</b>.`,
      x.change ? `Siang hari, dari terbit hingga Maghrib, ${x.longer ? 'bertambah' : 'berkurang'} dari ${x.dayFirst} menjadi ${x.dayLast} sepanjang bulan (${x.longer ? '+' : '−'}${x.change}).` : `Siang hari tetap sekitar ${x.dayFirst} sepanjang bulan.`,
      x.dst && `Jam ${x.dst.fwd ? 'dimajukan' : 'dimundurkan'} satu jam pada ${x.dst.date}; tabel sudah memperhitungkannya.`,
      x.ram && (x.ram.date ? `Ramadan ${x.ram.year} diperkirakan dimulai pada ${x.ram.date}.` : `Sebagian Ramadan ${x.ram.year} jatuh pada bulan ini.`),
      x.eidF && `Idulfitri diperkirakan pada ${x.eidF}.`,
      x.eidA && `Iduladha diperkirakan pada ${x.eidA}.`,
    ],
    faq: (x) => [
      [`Jam berapa Subuh di ${x.n} pada ${x.mo}?`, `Subuh di ${x.n} antara ${x.fajrE} (${x.fajrEd}) dan ${x.fajrL} (${x.fajrLd}) pada ${x.mo}. Tabel di atas memuat waktu setiap hari.`],
      [`Jam berapa Maghrib di ${x.n} pada ${x.mo}?`, `Maghrib di ${x.n} antara ${x.magE} (${x.magEd}) dan ${x.magL} (${x.magLd}) pada ${x.mo}.`],
      ['Metode perhitungan apa yang dipakai?', `${x.m}, dengan Asar ${x.a}. Masjid Anda bisa berbeda beberapa menit; ikuti jadwalnya untuk berjamaah.`],
      ...(x.ram ? [[`Kapan sahur dan berbuka di ${x.n} saat Ramadan ${x.ram.year}?`, 'Sahur berakhir saat Subuh dan berbuka saat Maghrib. Hari Ramadan ditandai di tabel; awal puasa tergantung rukyat.']] : []),
    ],
  },
  ms: {
    dur: (h, m) => (h ? `${h} jam ${m} minit` : `${m} minit`),
    introH: (n, mo) => `${n} pada ${mo}`,
    intro: (x) => [
      `Subuh paling awal pada ${x.fajrEd} jam <b>${x.fajrE}</b> dan paling lewat pada ${x.fajrLd} jam <b>${x.fajrL}</b>.`,
      `Maghrib (berbuka) paling awal pada ${x.magEd} jam <b>${x.magE}</b> dan paling lewat pada ${x.magLd} jam <b>${x.magL}</b>.`,
      x.change ? `Siang, dari syuruk hingga Maghrib, ${x.longer ? 'bertambah' : 'berkurang'} daripada ${x.dayFirst} kepada ${x.dayLast} sepanjang bulan (${x.longer ? '+' : '−'}${x.change}).` : `Siang kekal sekitar ${x.dayFirst} sepanjang bulan.`,
      x.dst && `Jam ${x.dst.fwd ? 'dicepatkan' : 'dilambatkan'} sejam pada ${x.dst.date}; jadual sudah mengambil kira perubahan ini.`,
      x.ram && (x.ram.date ? `Ramadan ${x.ram.year} dijangka bermula pada ${x.ram.date}.` : `Sebahagian Ramadan ${x.ram.year} jatuh dalam bulan ini.`),
      x.eidF && `Aidilfitri dijangka pada ${x.eidF}.`,
      x.eidA && `Aidiladha dijangka pada ${x.eidA}.`,
    ],
    faq: (x) => [
      [`Pukul berapa Subuh di ${x.n} pada ${x.mo}?`, `Subuh di ${x.n} antara ${x.fajrE} (${x.fajrEd}) dan ${x.fajrL} (${x.fajrLd}) pada ${x.mo}. Jadual di atas memuatkan waktu setiap hari.`],
      [`Pukul berapa Maghrib di ${x.n} pada ${x.mo}?`, `Maghrib di ${x.n} antara ${x.magE} (${x.magEd}) dan ${x.magL} (${x.magLd}) pada ${x.mo}.`],
      ['Kaedah pengiraan apa yang digunakan?', `${x.m}, dengan Asar ${x.a}. Masjid anda mungkin berbeza beberapa minit; ikut jadualnya untuk berjemaah.`],
      ...(x.ram ? [[`Bila sahur dan berbuka di ${x.n} semasa Ramadan ${x.ram.year}?`, 'Sahur berakhir pada Subuh dan berbuka pada Maghrib. Hari Ramadan ditanda dalam jadual; permulaannya bergantung pada rukyah.']] : []),
    ],
  },
  fr: {
    dur: (h, m) => (h ? `${h} h ${m} min` : `${m} min`),
    introH: (n, mo) => `${n} en ${mo}`,
    intro: (x) => [
      `Le Fajr est le plus tôt le ${x.fajrEd} à <b>${x.fajrE}</b> et le plus tard le ${x.fajrLd} à <b>${x.fajrL}</b>.`,
      `Le Maghrib (iftar) est le plus tôt le ${x.magEd} à <b>${x.magE}</b> et le plus tard le ${x.magLd} à <b>${x.magL}</b>.`,
      x.change ? `La journée, du lever du soleil au Maghrib, ${x.longer ? 's’allonge' : 'raccourcit'} de ${x.dayFirst} à ${x.dayLast} au cours du mois (${x.longer ? '+' : '−'}${x.change}).` : `La journée reste d’environ ${x.dayFirst} tout le mois.`,
      x.dst && `Les horloges ${x.dst.fwd ? 'avancent' : 'reculent'} d’une heure le ${x.dst.date} ; le tableau en tient déjà compte.`,
      x.ram && (x.ram.date ? `Le Ramadan ${x.ram.year} devrait commencer le ${x.ram.date}.` : `Une partie du Ramadan ${x.ram.year} tombe ce mois-ci.`),
      x.eidF && `L’Aïd al-Fitr est attendu le ${x.eidF}.`,
      x.eidA && `L’Aïd al-Adha est attendu le ${x.eidA}.`,
    ],
    faq: (x) => [
      [`À quelle heure est le Fajr à ${x.n} en ${x.mo} ?`, `Le Fajr à ${x.n} va de ${x.fajrE} (${x.fajrEd}) à ${x.fajrL} (${x.fajrLd}) en ${x.mo}. Le tableau ci-dessus donne l’heure de chaque jour.`],
      [`À quelle heure est le Maghrib à ${x.n} en ${x.mo} ?`, `Le Maghrib à ${x.n} va de ${x.magE} (${x.magEd}) à ${x.magL} (${x.magLd}) en ${x.mo}.`],
      ['Quelle méthode de calcul est utilisée ?', `${x.m}, avec l’Asr ${x.a}. Votre mosquée peut différer de quelques minutes ; suivez son horaire pour la prière en commun.`],
      ...(x.ram ? [[`Quand sont le suhoor et l’iftar à ${x.n} pendant le Ramadan ${x.ram.year} ?`, 'Le suhoor se termine au Fajr et l’iftar a lieu au Maghrib. Les jours de Ramadan sont surlignés ; le début dépend de l’observation de la lune.']] : []),
    ],
  },
  tr: {
    dur: (h, m) => (h ? `${h} sa ${m} dk` : `${m} dk`),
    introH: (n, mo) => `${n}, ${mo}`,
    intro: (x) => [
      `İmsak en erken ${x.fajrEd} günü <b>${x.fajrE}</b>, en geç ${x.fajrLd} günü <b>${x.fajrL}</b>.`,
      `Akşam (iftar) en erken ${x.magEd} günü <b>${x.magE}</b>, en geç ${x.magLd} günü <b>${x.magL}</b>.`,
      x.change ? `Güneşin doğuşundan akşama kadar gündüz ay boyunca ${x.dayFirst} süresinden ${x.dayLast} süresine ${x.longer ? 'uzar' : 'kısalır'} (${x.longer ? '+' : '−'}${x.change}).` : `Gündüz ay boyunca yaklaşık ${x.dayFirst} kalır.`,
      x.dst && `Saatler ${x.dst.date} günü bir saat ${x.dst.fwd ? 'ileri' : 'geri'} alınır; tablo bu değişikliği içerir.`,
      x.ram && (x.ram.date ? `Ramazan ${x.ram.year}’in ${x.ram.date} günü başlaması bekleniyor.` : `Ramazan ${x.ram.year}’in bir kısmı bu aya denk gelir.`),
      x.eidF && `Ramazan Bayramı ${x.eidF} günü bekleniyor.`,
      x.eidA && `Kurban Bayramı ${x.eidA} günü bekleniyor.`,
    ],
    faq: (x) => [
      [`${x.mo} ayında ${x.n} için imsak saat kaçta?`, `${x.mo} ayında ${x.n} için imsak ${x.fajrE} (${x.fajrEd}) ile ${x.fajrL} (${x.fajrLd}) arasındadır. Yukarıdaki tabloda her günün vakti var.`],
      [`${x.mo} ayında ${x.n} için akşam ezanı saat kaçta?`, `${x.mo} ayında ${x.n} için akşam ${x.magE} (${x.magEd}) ile ${x.magL} (${x.magLd}) arasındadır.`],
      ['Hangi hesaplama yöntemi kullanılıyor?', `${x.m}, ikindi ${x.a}. Caminiz birkaç dakika farklı olabilir; cemaat için caminin vakitlerine uyun.`],
      ...(x.ram ? [[`Ramazan ${x.ram.year}’de ${x.n} için sahur ve iftar ne zaman?`, 'Sahur imsakta biter, iftar akşam vaktindedir. Ramazan günleri tabloda vurgulanmıştır; başlangıç hilal gözlemine bağlıdır.']] : []),
    ],
  },
};
